 json::check(!policy.fusion&&!policy.tiling&&!policy.constant_reuse&&!policy.inplace,"optimization unavailable until U19");json::check(caps.contexts==1&&!caps.preempt&&caps.max_objects>0&&caps.max_objects<=64&&caps.max_pending>0&&caps.max_pending<=32&&caps.max_completions>0&&caps.max_completions<=64&&caps.max_refs_per_job<=8&&caps.alignment>=64&&!(caps.alignment&(caps.alignment-1)),"unsupported device caps");
