 auto*programs=json::member(q,"programs");std::set<std::tuple<uint32_t,uint32_t,uint32_t>> program_keys;std::set<Digest> codes;for(size_t i=0;i<json::count(programs,caps.max_programs);i++){auto*r=json::at(programs,i);json::fields(r,{"namespace","profile","program","code","schema"});vxunified::ProgramKey key;key.namespace_id=json::u32(json::member(r,"namespace"));key.logical_profile=json::u32(json::member(r,"profile"));key.logical_program=json::u32(json::member(r,"program"));key.code=json::digest(json::member(r,"code"));key.schema=json::digest(json::member(r,"schema"));key.hardware_contract=hw.hardware_contract;json::check(bool(vxunified::admit_program(hw,key))&&program_keys.emplace(key.namespace_id,key.logical_profile,key.logical_program).second,"program admission");plan.programs.push_back(key);codes.insert(key.code);}
 auto numeric=json::parse(package.numeric_contract_json());json::check(json::u64(json::member(numeric.get(),"schema"))==1,"numeric schema"); // Retain the complete frozen numeric contract; no precision waiver here.
 auto graph=json::parse(package.graph_json());auto*g=graph.get();json::fields(g,{"schema","tensors","nodes","inputs","outputs","shape_profiles"});json::check(json::u64(json::member(g,"schema"))==1,"graph schema");
 std::map<TensorId,Shape> overrides;auto*profiles=json::member(g,"shape_profiles");std::set<std::string> profile_names;
 for(size_t i=0;i<json::count(profiles,32);i++){auto*p=json::at(profiles,i);json::fields(p,{"name","shapes"});auto name=json::str(json::member(p,"name"));json::check(!name.empty()&&name.size()<=64&&profile_names.insert(name).second,"shape profile identity");auto*ss=json::member(p,"shapes");std::map<TensorId,Shape> entries;for(size_t j=0;j<json::count(ss);j++){auto*r=json::at(ss,j);json::fields(r,{"id","shape"});json::check(entries.emplace(json::u32(json::member(r,"id")),shape(json::member(r,"shape"))).second,"duplicate profile tensor");}if(name==policy.shape_profile)overrides=std::move(entries);}
 json::check(policy.shape_profile.empty()||profile_names.count(policy.shape_profile),"unlisted dynamic profile");std::map<TensorId,TensorDesc> tensors;auto*ts=json::member(g,"tensors");
 for(size_t i=0;i<json::count(ts);i++){auto*r=json::at(ts,i);json::fields(r,{"id","dtype","layout","shape","domain","access","alignment","constant","asset"});TensorDesc t;t.id=json::u32(json::member(r,"id"));json::check(t.id&&t.id<0xffff0000U,"tensor id");auto dtype=json::str(json::member(r,"dtype"));if(dtype=="FP32")t.dtype=DType::FP32;else if(dtype=="I16")t.dtype=DType::I16;else if(dtype=="I48")t.dtype=DType::I48;else if(dtype=="U8")t.dtype=DType::U8;else if(dtype=="I32")t.dtype=DType::I32;else if(dtype=="FP16")t.dtype=DType::FP16;else throw std::runtime_error("unsupported tensor dtype");t.layout=json::str(json::member(r,"layout"));json::check(!t.layout.empty()&&t.layout.size()<=32,"tensor layout");t.shape=shape(json::member(r,"shape"),true);auto o=overrides.find(t.id);if(o!=overrides.end()){json::check(o->second.size()==t.shape.size(),"profile rank");for(size_t k=0;k<t.shape.size();k++)json::check(!t.shape[k]||t.shape[k]==o->second[k],"profile changes static dimension");t.shape=o->second;overrides.erase(o);}t.bytes=tensor_bytes(t);auto domain=json::str(json::member(r,"domain"));if(domain=="CPU")t.domain=AddressDomain::CPU;else if(domain=="PS")t.domain=AddressDomain::PS;else if(domain=="PL")t.domain=AddressDomain::PL;else throw std::runtime_error("tensor address domain");t.access=json::u32(json::member(r,"access"));t.alignment=json::u64(json::member(r,"alignment"));t.constant=json::boolean(json::member(r,"constant"));json::check(t.access&&!(t.access&~3U)&&t.alignment>=caps.alignment&&t.alignment<=(1U<<20)&&!(t.alignment&(t.alignment-1))&&(!t.constant||t.access==1),"tensor access/alignment");if(t.constant){json::check(json::has(r,"asset"),"constant requires immutable asset");t.asset=json::str(json::member(r,"asset"));auto asset=package.assets().find(t.asset);json::check(asset!=package.assets().end()&&asset->second.type=="binary"&&asset->second.role=="weights"&&asset->second.content->size()==t.bytes,"constant asset binding/length");t.content_sha=asset->second.sha;}else json::check(!json::has(r,"asset"),"mutable tensor cannot bind constant asset");json::check(tensors.emplace(t.id,t).second,"duplicate tensor");}
 json::check(overrides.empty(),"profile unknown tensor");plan.inputs=ids(json::member(g,"inputs"));plan.outputs=ids(json::member(g,"outputs"));json::check(!plan.outputs.empty(),"graph has no outputs");std::set<TensorId> sources(plan.inputs.begin(),plan.inputs.end());for(auto&kv:tensors)if(kv.second.constant)sources.insert(kv.first);for(auto id:sources)json::check(tensors.count(id),"unknown graph input");for(auto id:plan.outputs)json::check(tensors.count(id),"unknown graph output");
 struct Pending {PlannedNode plan;std::set<NodeId> dependencies;};std::map<NodeId,Pending> pending;std::map<TensorId,NodeId> producer;auto*ns=json::member(g,"nodes");
 for(size_t i=0;i<json::count(ns);i++){auto*r=json::at(ns,i);json::fields(r,{"id","operator","inputs","outputs","parameters","job_count","evidence_bytes","program_requirements"});Pending p;auto&n=p.plan.node;n.id=json::u32(json::member(r,"id"));json::check(n.id!=0,"node id");auto*op=json::member(r,"operator");json::fields(op,{"name","version","implementation_sha"});n.key={json::str(json::member(op,"name")),json::str(json::member(op,"version")),json::digest(json::member(op,"implementation_sha"))};n.inputs=ids(json::member(r,"inputs"));n.outputs=ids(json::member(r,"outputs"));json::check(!n.outputs.empty(),"node output required");for(auto id:n.inputs)json::check(tensors.count(id)&&(tensors.at(id).access&1),"unknown or unreadable node input");for(auto id:n.outputs)json::check(tensors.count(id)&&!sources.count(id)&&(tensors.at(id).access&2)&&producer.emplace(id,n.id).second,"output already defined or not writable");n.parameters=params(json::member(r,"parameters"));p.plan.job_count=json::u64(json::member(r,"job_count"));p.plan.evidence_bytes=json::u64(json::member(r,"evidence_bytes"));plan.total_jobs=json::add(plan.total_jobs,p.plan.job_count);plan.evidence_bytes=json::add(plan.evidence_bytes,p.plan.evidence_bytes);json::check(plan.total_jobs<=package.declared_max_jobs()&&plan.evidence_bytes<=package.declared_max_evidence_bytes(),"graph actual job/evidence budget");auto*prs=json::member(r,"program_requirements");for(size_t j=0;j<json::count(prs,caps.max_programs);j++){auto d=json::digest(json::at(prs,j));json::check(codes.count(d),"node requires unbound program");n.program_requirements.push_back(d);}json::check(!p.plan.job_count||!n.program_requirements.empty(),"GPU jobs require bound program");json::check(pending.emplace(n.id,std::move(p)).second,"duplicate node");}
 for(auto&kv:pending)for(auto id:kv.second.plan.node.inputs){auto it=producer.find(id);if(it!=producer.end())kv.second.dependencies.insert(it->second);else json::check(sources.count(id),"unproduced input");}
 for(auto id:plan.outputs){json::check(sources.count(id)||producer.count(id),"unproduced graph output");}
 std::set<NodeId> done;
 while(done.size()<pending.size()){bool advanced=false;for(auto&kv:pending){if(done.count(kv.first)||!std::all_of(kv.second.dependencies.begin(),kv.second.dependencies.end(),[&](NodeId id){return done.count(id);}))continue;auto p=kv.second.plan;auto&n=p.node;std::vector<TensorDesc> in,out;for(auto id:n.inputs)in.push_back(tensors.at(id));for(auto id:n.outputs)out.push_back(tensors.at(id));auto resolved=registry.resolve(n.key.name,n.key.semantic_version,n.key.implementation_sha);json::check(bool(resolved),"unregistered operator implementation");auto&op=*resolved.value;auto valid=registry.validate(n.key,in,n.parameters,caps);json::check(bool(valid),valid.error?valid.error->detail:"operator validation");for(auto&t:out)json::check(std::find(op.supported_types.begin(),op.supported_types.end(),t.dtype)!=op.supported_types.end()&&std::find(op.supported_layouts.begin(),op.supported_layouts.end(),t.layout)!=op.supported_layouts.end(),"output type/layout");auto inferred=op.infer_shapes(in,n.parameters,caps);json::check(bool(inferred)&&inferred.value->size()==out.size(),"shape inference failed");for(size_t i=0;i<out.size();i++)json::check((*inferred.value)[i]==out[i].shape,"declared shape differs");auto workspace=op.workspace(in,n.parameters,caps);json::check(bool(workspace),"workspace inference");p.workspace_bytes=*workspace.value;auto prepared=op.prepare(n.id,in,out,n.parameters,caps);json::check(bool(prepared)&&prepared.value->id==n.id&&!(prepared.value->key<n.key)&&!(n.key<prepared.value->key)&&prepared.value->inputs==n.inputs&&prepared.value->outputs==n.outputs&&prepared.value->parameters==n.parameters,"operator prepare changed graph identity");if(!prepared.value->program_requirements.empty())json::check(prepared.value->program_requirements==n.program_requirements,"operator program contract differs");plan.nodes.push_back(std::move(p));done.insert(kv.first);advanced=true;}json::check(advanced,"graph cycle");}
 std::map<TensorId,std::pair<uint64_t,uint64_t>> lifetime;for(auto id:sources)lifetime[id]={0,0};for(size_t i=0;i<plan.nodes.size();i++){auto&n=plan.nodes[i].node;for(auto id:n.outputs)lifetime[id]={i+1,i+1};for(auto id:n.inputs)lifetime.at(id).second=std::max(lifetime.at(id).second,uint64_t(i+1));}for(auto id:plan.outputs)lifetime.at(id).second=plan.nodes.size()+1;for(auto&kv:tensors){json::check(lifetime.count(kv.first),"unused tensor");auto life=lifetime.at(kv.first);if(kv.second.constant)life.second=UINT64_MAX;plan.tensors.push_back({kv.second,life.first,life.second});}
